/* Mahalanobis 이상탐지기 (전체 데이터셋 정상 데이터로 학습됨, 8개 피처) */
static const double MAHA_MEAN[8] = {0.0741937906, 16.7115669250, 0.0000000000, 1.8825006485, 48.5961380005, 136.4123382568, 1.0791354179, 0.3429868519};
static const double MAHA_INV_COV[64] = {531.2539977646, 0.9552439760, -0.0000000000, -6.2819486392, 0.0630773465, -0.0000027247, -0.4881195369, -6.9178992079, 0.9552439760, 0.1080547046, 0.0000000000, -0.0226035506, 0.0003736740, -0.0000002222, 0.0226933998, -0.0181808712, 0.0000000000, 0.0000000000, 1000000.0000000000, 0.0000000000, 0.0000000000, 0.0000000000, 0.0000000000, 0.0000000000, -6.2819486392, -0.0226035506, 0.0000000000, 3.6675901344, -0.0765270076, 0.0000012154, -0.5575000455, 2.9760269486, 0.0630773465, 0.0003736740, -0.0000000000, -0.0765270076, 0.0027133694, -0.0000000136, 0.0047848226, -0.0639116518, -0.0000027247, -0.0000002222, -0.0000000000, 0.0000012154, -0.0000000136, 0.0000000074, 0.0000004564, -0.0000036404, -0.4881195369, 0.0226933998, 0.0000000000, -0.5575000455, 0.0047848226, 0.0000004564, 1.0467047870, -0.1168817490, -6.9178992079, -0.0181808712, 0.0000000000, 2.9760269486, -0.0639116518, -0.0000036404, -0.1168817490, 32.2518945337};
static const double MAHA_THRESHOLD = 10.6895155838;

int maha_predict(double *x) {
    double diff[8];
    for (int i = 0; i < 8; i++) diff[i] = x[i] - MAHA_MEAN[i];
    double dist2 = 0.0;
    for (int i = 0; i < 8; i++) {
        double s = 0.0;
        for (int j = 0; j < 8; j++) s += MAHA_INV_COV[i * 8 + j] * diff[j];
        dist2 += diff[i] * s;
    }
    double dist = sqrt(dist2);
    return dist > MAHA_THRESHOLD ? 1 : 0;
}

#define NORMAL_IDX 2
static const int CODE_MAP[5] = {1, 2, 0, 3, 4};

int can_ids_predict(double *x) {
    double scores[5];
    score(x, scores);
    int best = 0;
    for (int i = 1; i < 5; i++) if (scores[i] > scores[best]) best = i;
    if (best != NORMAL_IDX) return CODE_MAP[best];
    if (maha_predict(x)) return 5;
    return 0;
}
